# Primary Assessment, part 1: responsiveness, airway and breathing (NREMT EMR test plan, 2025:
# Primary Assessment 37% to 41%, split by Tigertest into this domain and emrCirc).
# EMR airway scope (National EMS Scope of Practice Model 2019): head tilt-chin lift, jaw thrust,
# oral airway, upper-airway suctioning, mouth-to-barrier, mouth-to-mask, mouth-to-stoma, BVM,
# manual removal of airway obstruction, oxygen by nasal cannula and nonrebreather. Nasal airways,
# supraglottic airways, CPAP and pulse oximetry are EMT or higher and appear only as wrong options
# or scope questions. Choking follows the 2025 AHA guidelines (news release, October 22, 2025).
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Level of consciousness", "A patient opens her eyes and groans only when you squeeze her shoulder. Using AVPU, how is she described?",
      ["Responds to pain", "Alert", "Responds to verbal", "Unresponsive"],
      "She does not respond to your voice but does react to a painful stimulus, so she is P on the AVPU scale. A patient who responds to nothing is U."),
    S(1, 1, "Opening the airway", "An unresponsive woman found in bed has no sign of injury. Which maneuver opens her airway?",
      ["Head tilt-chin lift", "Jaw thrust only", "Turning the head side to side", "Pulling the tongue forward with gauze"],
      "With no suspected neck injury, the head tilt-chin lift lifts the tongue off the back of the throat. The jaw thrust is kept for patients who may have a spine injury."),
    S(1, 2, "Oral airway", "When is an oral airway the right adjunct?",
      ["An unresponsive patient with no gag reflex", "A confused patient who is talking", "A patient who gags when you check the mouth", "A patient with clenched teeth"],
      "An oral airway keeps the tongue from blocking the airway in a patient who cannot protect it. A gag reflex or clenched teeth mean the device can cause vomiting or injury."),
    S(1, 2, "Oral airway sizing", "How do you choose the right size oral airway?",
      ["Corner of the mouth to the earlobe", "Tip of the nose to the point of the chin", "Width of the patient's palm across the knuckles", "Length of the patient's index finger"],
      "Hold the airway against the face: it should reach from the corner of the mouth to the bottom of the earlobe or the angle of the jaw. Too long can push the epiglottis closed; too short can push the tongue back."),
    S(1, 2, "Suction", "While you ventilate an unresponsive man, he vomits and you hear gurgling. What should you do first?",
      ["Suction the mouth", "Give faster breaths", "Insert a larger oral airway", "Raise his head on a pillow"],
      "Gurgling means fluid in the upper airway. Roll him if needed and suction before you go on ventilating, or the vomit will be pushed into the lungs."),
    S(1, 3, "Breathing assessment", "An adult breathes 8 times a minute with shallow chest rise and gray lips. What does she need?",
      ["Ventilations with a BVM and oxygen", "A nasal cannula at 2 L/min", "A nonrebreather mask with no other care", "Time to rest, then a full reassessment"],
      "A slow rate with shallow breaths is inadequate breathing, even though she breathes on her own. She needs assisted ventilation; a mask alone gives oxygen but does not move enough air."),
    S(1, 2, "Rescue breathing", "An adult has a strong pulse but is not breathing. How often do you give a rescue breath?",
      ["Every 6 seconds", "Every 2 to 3 seconds", "Every 10 seconds", "Every 15 seconds"],
      "An adult with a pulse who is not breathing gets 1 breath every 6 seconds, about 10 a minute, each just enough to make the chest rise. Children and infants get a breath every 2 to 3 seconds."),
    S(1, 2, "Choking", "A conscious adult at a restaurant clutches her throat and cannot speak or cough. What does current AHA guidance say to do?",
      ["Alternate 5 back blows and 5 abdominal thrusts", "Give abdominal thrusts only", "Do a blind finger sweep", "Lay her down on the floor and give rescue breaths"],
      "The 2025 AHA guidelines tell rescuers to alternate 5 back blows with 5 abdominal thrusts for a choking adult or child until the object comes out or the person becomes unresponsive."),
    M(1, 2, "Inadequate breathing", "Which findings show an adult's breathing is not adequate? Select three.",
      ["Use of neck muscles to breathe", "Speaking only 1 or 2 words at a time", "Blue tint around the lips", "Rate of 16 with even rise", "Speaking in full sentences", "Pink, dry skin"],
      "Accessory muscle use, broken speech and cyanosis are signs of failing breathing. A rate of 16 with equal chest rise, full sentences and normal skin are signs of adequate breathing."),
    O(1, 2, "Mouth-to-mask ventilation", "Put the steps for mouth-to-mask ventilation of an adult in order.",
      ["Place the mask on the face", "Seal it with both hands", "Open the airway", "Breathe in until the chest rises", "Let the chest fall before the next breath"],
      "Position and seal the mask, open the airway while holding the seal, give each breath over about a second until the chest just rises and let it fall before the next one."),
    S(1, 3, "Stoma", "A patient who breathes through a neck stoma stops breathing. How do you ventilate him?",
      ["Seal a pediatric mask over the stoma", "Seal a mask over his mouth and nose as usual", "Give breaths through the nose only", "Wait for a paramedic to place an advanced airway"],
      "A patient with a stoma moves air through the opening in his neck, not the mouth. A small round mask sealed over the stoma gives effective breaths."),
    S(1, 2, "Recovery position", "An unresponsive patient is breathing well and has no suspected injury. Why place her in the recovery position?",
      ["To let fluids drain from the mouth", "To raise her blood pressure while she rests", "To make chest compressions easier if she arrests", "To keep her from waking up too quickly"],
      "Lying on her side lets vomit and saliva drain out instead of into the airway, while you keep watching her breathing."),
    # ---------- Practice Test 2 ----------
    S(2, 1, "Level of consciousness", "A man answers your questions but cannot tell you the day or where he is. How do you describe him on AVPU?",
      ["Alert but disoriented", "Responds to verbal stimulus", "Responds to pain", "Unresponsive"],
      "He is awake with eyes open and talking on his own, so he is Alert on AVPU. His confusion is described separately as disorientation to time and place."),
    S(2, 2, "Jaw thrust", "An unresponsive cyclist was thrown over a car hood. Which maneuver opens her airway?",
      ["Jaw thrust", "Head tilt-chin lift", "Neck roll under the shoulders", "Recovery position first"],
      "With a mechanism that could injure the spine, the jaw thrust opens the airway with little neck movement. If it fails to open the airway, the airway still takes priority."),
    S(2, 2, "Nasal airway", "An unresponsive patient has clenched teeth and snoring breaths. Under the national scope model, which airway adjunct is outside EMR scope?",
      ["A nasal airway", "An oral airway", "A bag-valve mask", "A suction catheter for the mouth"],
      "The national scope model lists the nasal airway at the EMT level and above. An EMR uses manual maneuvers, suction, an oral airway when there is no gag reflex, and a BVM."),
    S(2, 2, "Suction", "Why should each suction attempt on an adult be kept short?",
      ["Suction removes oxygen too", "It drains the suction battery", "Long suction cools the airway", "It loosens the patient's teeth"],
      "Suction pulls out air along with fluid, so long attempts cause low oxygen. Keep each attempt brief, about 15 seconds or less for an adult, and oxygenate between attempts."),
    S(2, 2, "Choking infant", "A 6-month-old is choking and cannot cry or cough. What does current AHA guidance say to do?",
      ["Alternate 5 back blows and 5 chest thrusts", "Give abdominal thrusts", "Do a blind finger sweep", "Hold the infant upside down by the ankles and shake"],
      "For a choking infant, the 2025 AHA guidelines call for 5 back blows alternating with 5 chest thrusts using the heel of one hand. Abdominal thrusts are not used in infants because of injury risk."),
    S(2, 3, "Unresponsive choking", "A choking adult goes limp in your arms. What do you do after lowering him to the floor?",
      ["Start CPR, checking the mouth before breaths", "Keep giving abdominal thrusts until the object comes out", "Do a blind finger sweep", "Give back blows to him on the floor"],
      "Once a choking patient becomes unresponsive, start CPR. Compressions may move the object. Each time you open the airway to give breaths, look in the mouth and remove an object only if you can see it."),
    S(2, 2, "Gastric distension", "While you ventilate a child with a BVM, her belly swells. What should you change?",
      ["Give slower, smaller breaths", "Squeeze the bag harder so more air goes in", "Breathe faster to keep up with her rate", "Press on the belly to empty it"],
      "Air going into the stomach means breaths are too big or too fast. Smaller, slower breaths that just make the chest rise reduce distension; pressing on the belly can cause vomiting."),
    M(2, 2, "Airway obstruction", "Which signs point to a severe airway obstruction? Select two.",
      ["No sound when trying to speak", "A weak, silent cough", "Forceful coughing", "Clear, loud speech", "Normal breathing between coughs"],
      "A person who cannot speak or has a weak, silent cough is not moving enough air and needs help now. Forceful coughing and clear speech mean the airway is partly open, so encourage coughing and watch closely."),
    X(2, 2, "EMR scope", "Under the national scope model, is each airway skill within EMR scope?",
      ["Oral airway", "Supraglottic airway", "Upper airway suctioning", "CPAP", "Mouth-to-stoma breathing"],
      ["Within EMR scope", "Above EMR scope"], [0, 1, 0, 1, 0],
      "The national model gives EMRs the oral airway, upper airway suction and all the mouth-to-barrier methods, including through a stoma. Supraglottic airways are AEMT and above, and CPAP is EMT and above."),
    S(2, 2, "Breathing assessment", "How long should you look, listen and feel for breathing in an unresponsive adult before acting?",
      ["No more than 10 seconds", "About 30 seconds", "A full minute of watching and listening", "Until a second responder arrives"],
      "Check breathing, and the pulse at the same time if you are trained to, for no more than 10 seconds. Gasping is not normal breathing and calls for CPR."),
    S(2, 2, "Oxygen by nasal cannula", "An alert patient breathing adequately is mildly short of breath. Your protocol calls for low-flow oxygen. Which device fits?",
      ["Nasal cannula", "Bag-valve mask", "Oral airway", "Mouth-to-mask breaths"],
      "A patient who is breathing adequately needs oxygen, not ventilation. A nasal cannula gives low-flow oxygen and is within EMR scope. A BVM and rescue breaths are for inadequate breathing."),
    M(2, 3, "Infant breathing", "Which signs show an infant is working too hard to breathe? Select three.",
      ["Nostrils flaring with each breath", "Skin pulling in between the ribs", "Grunting at the end of each breath", "Pink lips and quiet breathing", "Feeding well from a bottle", "Sleeping calmly"],
      "Nasal flaring, retractions between the ribs and grunting are signs of respiratory distress in an infant. Pink lips, quiet breathing, good feeding and calm sleep are reassuring."),
    # ---------- Drill only ----------
    S(0, 1, "Airway priority", "Why is the airway checked before almost everything else?",
      ["Without it, oxygen cannot reach the lungs", "It is the easiest step to do", "It takes the least time", "It tells you the patient's history and medicines"],
      "Every other treatment fails if air cannot reach the lungs. A blocked airway can kill within minutes, so it comes first in the primary assessment along with major bleeding."),
    S(0, 2, "Agonal breathing", "An unresponsive man takes a slow gasp every 10 seconds. How should you treat this?",
      ["As no normal breathing", "As adequate breathing for now", "As a sign he is waking up", "As a reason to wait and watch him"],
      "Occasional gasps, called agonal breaths, are a sign of cardiac arrest, not real breathing. If he has no pulse, start CPR."),
    S(0, 2, "Oral airway insertion", "In an adult, how is an oral airway usually inserted?",
      ["Tip toward the roof of the mouth, then rotated", "Tip pointing toward the tongue and pushed straight in", "Through one nostril", "Sideways along the cheek and left there"],
      "In adults the airway goes in with the tip pointing to the roof of the mouth and is turned 180 degrees as it nears the back of the throat, so it rides over the tongue. In children it is often inserted with a tongue blade in its normal position."),
    S(0, 2, "BVM seal", "Why is a two-person BVM technique preferred when two responders are present?",
      ["One holds a better mask seal", "It doubles the oxygen flow from the tank", "It lets breaths be twice as large", "It avoids the need to open the airway"],
      "One rescuer uses both hands to hold the mask seal and keep the airway open while the other squeezes the bag. A poor seal is the most common reason BVM breaths fail."),
    S(0, 2, "Pediatric airway", "Why might a folded towel go under a small child's shoulders when you open the airway?",
      ["The large head bends the neck forward", "It stops the child from moving or rolling", "It keeps the child warm on a cold floor", "It lowers the risk of vomiting during ventilation"],
      "A young child's large head flexes the neck when lying flat, which can kink the airway. A little padding under the shoulders brings the head to a neutral position."),
    S(0, 1, "Breathing rate", "Which breathing rate is normal for a resting adult?",
      ["16 a minute", "6 a minute", "32 a minute", "40 a minute"],
      "A resting adult normally breathes about 12 to 20 times a minute, so 16 is normal. Rates well below or above that range, along with poor chest rise, suggest inadequate breathing."),
    M(0, 2, "Rescue breaths", "Which make rescue breaths more effective? Select two.",
      ["Each breath over about 1 second", "Just enough air to see the chest rise", "Breaths as fast as possible", "Blowing until the cheeks puff", "Skipping the airway opening"],
      "Steady one-second breaths that just raise the chest give oxygen without filling the stomach. Fast or forceful breaths push air into the stomach and can cause vomiting."),
    S(0, 2, "Choking pregnant patient", "A choking woman is visibly pregnant. Where do you give thrusts?",
      ["On the chest", "On the upper belly", "On the lower belly", "Only on the back"],
      "In late pregnancy, and for people too large to encircle, chest thrusts replace abdominal thrusts so the uterus is not compressed."),
    S(0, 3, "Opioid overdose", "A man with pinpoint pupils breathes 4 times a minute. Before giving intranasal naloxone, what should you do?",
      ["Open the airway and ventilate", "Wait to see if he wakes up on his own", "Sit him upright in a chair so he can breathe", "Check his blood sugar with a meter first"],
      "Support breathing first. Breaths with a BVM or mask keep oxygen going while naloxone, which takes a few minutes to work, is prepared and given."),
    O(0, 2, "Unresponsive patient", "Put the first steps for an unresponsive adult found on a sidewalk in order.",
      ["Make sure the scene is safe", "Check for a response", "Call for help and an AED", "Check breathing and pulse"],
      "Confirm safety, tap and shout to check for a response, get help and an AED on the way, then check breathing and pulse together for no more than 10 seconds."),
]
